// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {RoundFactory} from "../src/RoundFactory.sol";

contract InvMutTest is Test {
    RoundFactory c;
    address owner;

    function setUp() public {
        c = new RoundFactory();
        owner = address(this);
        c.initialize();
    }

    function testFuzz_property(address newImpl) public {
        vm.assume(newImpl != address(0));

        vm.prank(owner);
        bool ok;
        try c.updateRoundImplementation(payable(newImpl)) {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule: the owner can always set a non-zero round implementation,
        // and the stored value must equal the value passed in.
        assertTrue(ok && c.roundImplementation() == newImpl);
    }
}
